          const parsed = JSON.parse(raw);
          if (Array.isArray(parsed) && parsed.every(b => b.id && b.title && b.author && b.tags && Array.isArray(b.tags))) {
            books = parsed;
          }
        }
      } catch (e) { /* ignore */ }
    }

    function save() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(books));
    }

    function render() {
      const list = document.getElementById('bookList');
      list.innerHTML = '';
      if (books.length === 0) {
        list.innerHTML = '<p>No books yet.</p>';
        return;
      }
      books.forEach(b => {
        const div = document.createElement('div');
        div.className = 'book';
        div.id = 'book-' + b.id;
        div.innerHTML = `
          <strong>${escapeHtml(b.title)}</strong> by ${escapeHtml(b.author)}<br>
          <span class="tags">${b.tags.map(t => `<label><input type="checkbox" name="tag-${b.id}" value="${t}" checked> ${escapeHtml(t)}</label>`).join('')}</span>
