  <title>Reading List</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 20px; }
    .book { border: 1px solid #ccc; padding: 10px; margin: 10px 0; }
    .book h3 { margin: 0 0 5px; }
    .book p { margin: 0 0 5px; }
    .book .tags { margin: 0; }
    .book .tags label { display: inline-block; margin-right: 5px; }
    .book .tags input[type="checkbox"] { margin-right: 5px; }
    .book .delete { float: right; }
    .book .delete button { background: #f44336; color: white; border: none; padding: 5px 10px; cursor: pointer; }
    .book .delete button:hover { background: #d32f2f; }
    .search-box { margin-bottom: 10px; }
    .search-box input { width: 100%; padding: 5px; }
    .export-box { margin-bottom: 10px; }
    .export-box button { background: #4caf50; color: white; border: none; padding: 5px 10px; cursor: pointer; }
    .export-box button:hover { background: #388e3c; }
    .import-box { margin-bottom: 10px; }
    .import-box input[type="file"] { margin-right: 5px; }
    .import-box button { background: #2196f3; color: white; border: none; padding: 5px 10px; cursor: pointer; }
    .import-box button:hover { background: #1976d2; }
    .alert { margin-top: 10px; padding: 10px; border: 1px solid #ccc; }
    .alert.error { background: #ffebee; color: #c62828; }
    .alert.success { background: #e8f5e9; color: #2e7d32; }
  </style>
</head>
<body>
  <h1>Reading List</h1>
  <div class="search-box">
    <input type="text" id="search-input" placeholder="Search books...">
  </div>
  <div class="export-box">
    <button id="export-btn">Export JSON</button>
  </div>
  <div class="import-box">
    <input type="file" id="import-file" accept=".json">
    <button id="import-btn">Import books</button>
  </div>
  <div id="books-container"></div>
  <div id="alert" class="alert" role="alert"></div>

  <script>
    const STORAGE_KEY = 'reading_list';
    let books = [];

    function loadBooks() {
      const data = localStorage.getItem(STORAGE_KEY);
      if (data) {
        try {
          books = JSON.parse(data);
        } catch (e) {
          books = [];
        }
      }
    }

    function saveBooks() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(books));
    }

    function renderBooks() {
      const container = document.getElementById('books-container');
      const search = document.getElementById('search-input').value.toLowerCase();
      const filtered = books.filter(book =>
        book.title.toLowerCase().includes(search) ||
        book.author.toLowerCase().includes(search)
      );
